const save = (key, value) => localStorage.setItem(key, JSON.stringify(value));
save("bashcrawl-web-hero-v1", { name: "Mira", role: "wanderer", tourDone: true });
save("bashcrawl-web-shell-v1", { mode: "story", onboarded: true, introSeen: true });
"seeded"

(async () => {
  // Measure what is painted: AppShell's ResizeObserver moves the button
  // in the frame the dock changes size, so let two frames go by first.
  await new Promise((done) => requestAnimationFrame(() => requestAnimationFrame(done)));
  const fab = document.querySelector("fleet-feedback").shadowRoot.querySelector(".fab").getBoundingClientRect();
  const box = (selector) => {
    const r = document.querySelector(selector)?.getBoundingClientRect();
    return r && r.height ? r : null;
  };
  const parts = { "prompt dock": box(".bc-dock-slot"), footer: box(".bc-footer") };
  const hits = Object.keys(parts).filter((name) => {
    const r = parts[name];
    return r && fab.bottom > r.top && fab.top < r.bottom && fab.right > r.left && fab.left < r.right;
  });
  if (hits.length) throw new Error(`the feedback button overlaps the ${hits.join(" and ")}`);
  return {
    button: [Math.round(fab.top), Math.round(fab.bottom)],
    dockTop: Math.round(parts["prompt dock"]?.top ?? 0),
    footerTop: Math.round(parts.footer?.top ?? 0),
  };
})()

